#!/usr/bin/env python3
"""Week 7 · harness for Task 3. Do not edit this file.

Both algorithms get the same points, the same starting centroids, and the same
distance function - which counts its calls.

    points     20,000 in 20 dimensions
    clusters   k = 12, well separated
    scored     distance computations
    checked    final SSE within 0.1% of the baseline

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, math, random, time

SEED, N, DIM, K = 246, 20_000, 20, 12


def build(seed=SEED):
    rng = random.Random(seed)
    centres = [tuple(rng.uniform(-20, 20) for _ in range(DIM)) for _ in range(K)]
    points = []
    for i in range(N):
        c = centres[i % K]
        points.append(tuple(v + rng.gauss(0, 1.2) for v in c))
    rng.shuffle(points)
    initial = rng.sample(points, K)
    return points, initial


class Distance:
    def __init__(self):
        self.calls = 0

    def __call__(self, a, b):
        self.calls += 1
        return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def sse(points, labels, centroids):
    total = 0.0
    for p, l in zip(points, labels):
        c = centroids[l]
        total += sum((x - y) ** 2 for x, y in zip(p, c))
    return total


def run(cls, label, points, initial):
    d = Distance()
    algo = cls(K)
    t0 = time.perf_counter()
    labels, centroids = algo.run(points, initial, d)
    elapsed = time.perf_counter() - t0
    s = sse(points, labels, centroids)
    print(f"  {label:<10} distances {d.calls:>12,}   sse {s:>14,.2f}   "
          f"{getattr(algo, 'iterations', '?'):>3} iters   {elapsed:>6.2f}s")
    return {"calls": d.calls, "sse": s, "time": elapsed}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    points, initial = build()
    print(f"\n  {N:,} points in {DIM} dimensions, k = {K}\n")

    from task3_fewer import NaiveKMeans
    base = run(NaiveKMeans, "baseline", points, initial)

    if a.yours:
        from task3_fewer import YourKMeans
        mine = run(YourKMeans, "yours", points, initial)
        print()
        drift = abs(mine["sse"] - base["sse"]) / base["sse"]
        if drift > 0.001:
            print(f"   FAIL  sse differs by {drift:.2%}, tolerance is 0.1%. "
                  f"Correctness first.")
        else:
            cut = 1 - mine["calls"] / base["calls"]
            print(f"   ok    sse matches to {drift:.4%}")
            print(f"   distance computations cut by {cut:.1%}  "
                  f"({mine['calls']:,} from {base['calls']:,})")
            grade = ("strong" if cut >= 0.70 else
                     "good" if cut >= 0.40 else
                     "pass" if cut > 0.05 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
